describe("booking e-mail samples", () => {
  it("every sample has its expectations, and every expectation a sample", () => {
    expect(readdirSync(DIR).filter((f) => f.endsWith(".eml")).sort()).toEqual(Object.keys(EXPECTED).sort());
  });

  for (const [file, want] of Object.entries(EXPECTED)) {
    it(file, () => {
      const got = read(file);
      const { listing, amount, ...rest } = want;
      expect(got).toMatchObject(rest);
      if (amount !== undefined) expect(got.amount).toEqual(amount);
      if (listing) expect(got.listing).toMatchObject(listing);
      expect(got.messageId).toMatch(/^fixture-/);
      // The excerpt is text, never markup.
      expect(got.excerpt).not.toMatch(/<\/?(html|td|div|style)\b/i);
    });
  }

  it("no sample holds a real-looking address, phone or card number", () => {
    for (const f of Object.keys(EXPECTED)) {
      const text = readFileSync(join(DIR, f), "latin1");
      expect(text, f).not.toMatch(/\+212\s?\d|\b\d{4} \d{4} \d{4} \d{4}\b/);
      for (const m of text.matchAll(/[\w.+-]+@([\w-]+\.)+[a-z]{2,}/gi)) {
        expect(m[0], f).toMatch(/(airbnb|booking|agoda|trip)\.(com|example)|\.example$|\.test$/i);
      }
    }
  });
});

describe("platform and subject helpers", () => {
  it("knows the platforms' sender domains, subdomains included", () => {
    expect(platformOfDomain("automated@em.airbnb.com".split("@")[1])).toBe("AIRBNB");
    expect(platformOfDomain("airbnb.fr")).toBe("AIRBNB");
    expect(platformOfDomain("mail.booking.com")).toBe("BOOKING");
    expect(platformOfDomain("agoda.com")).toBe("AGODA");
    expect(platformOfDomain("ctrip.com")).toBe("TRIPCOM");
    expect(platformOfDomain("notbooking.com")).toBeNull();
    expect(platformOfDomain("booking.com.evil.test")).toBeNull();
    expect(platformOfDomain(null)).toBeNull();
  });

  it("strips forward and reply prefixes in several languages", () => {
    expect(stripPrefixes("Fwd: TR: RE: Réservation confirmée")).toBe("Réservation confirmée");
    expect(stripPrefixes("RV: Reserva")).toBe("Reserva");
    expect(stripPrefixes("FW:Booking")).toBe("Booking");
  });

  it("an empty or broken message reads as not recognized, never throws", () => {
    expect(parseBookingEmail("")).toMatchObject({ platform: null, kind: "UNKNOWN", code: null });
    expect(parseBookingEmail("garbage without headers")).toMatchObject({ platform: null });
    expect(parseBookingEmail("Content-Type: multipart/mixed; boundary=x\r\n\r\n--x\r\n--x\r\n")).toMatchObject({ platform: null });
  });

  it("a date without a year after the e-mail's date goes to the next year; a stay over the new year keeps its order", () => {
    const raw = "From: Airbnb <automated@airbnb.com>\r\nSubject: Réservation confirmée - Test Nouvel An arrive le 30 déc.\r\nDate: Mon, 01 Nov 2027 10:00:00 +0000\r\nMessage-ID: <x@y>\r\n\r\nArrivée\r\njeu. 30 déc.\r\n\r\nDépart\r\nlun. 3 janv.\r\n\r\nCode de confirmation\r\nHMNEWYEAR1\r\n";
    expect(parseBookingEmail(raw)).toMatchObject({ checkIn: "2027-12-30", checkOut: "2028-01-03", code: "HMNEWYEAR1" });
  });
});
